SELECT (SELECT CAST(COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_rate FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN icustays i ON a.subject_id = i.subject_id JOIN charlson_comorbidities c ON a.subject_id = c.subject_id WHERE p.gender = 1 AND p.anchor_age = 44 AND i.los <= 10 AND c.score <= 5 AND a.dischtime - a.admittime <= 3) AS non_icu_mortality_rate, (SELECT CAST(COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_rate FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN icustays i ON a.subject_id = i.subject_id JOIN charlson_comorbidities c ON a.subject_id = c.subject_id WHERE p.gender = 1 AND p.anchor_age = 44 AND i.los <= 10 AND c.score <= 5 AND a.dischtime - a.admittime <= 3 AND i.careunit = 'ICU') AS icu_mortality_rate, (SELECT CAST(COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_rate FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN icustays i ON a.subject_id = i.subject_id JOIN charlson_comorbidities c ON a.subject_id = c.subject_id WHERE p.gender = 1 AND p.anchor_age = 44 AND i.los <= 10 AND c.score <= 5 AND a.dischtime - a.admittime <= 3 AND i.careunit = 'ICU' AND (SELECT COUNT(*) FROM labevents l WHERE l.subject_id = a.subject_id AND l.itemid = 257075) > 0) AS icu_mortality_with_ventilation_rate, (SELECT CAST(COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_rate FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN icustays i ON a.subject_id = i.subject_id JOIN charlson_comorbidities c ON a.subject_id = c.subject_id WHERE p.gender = 1 AND p.anchor_age = 44 AND i.los <= 10 AND c.score <= 5 AND a.dischtime - a.admittime <= 3 AND i.careunit = 'ICU' AND (SEL